import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SAVE-TRANSLATE-_002fTYPE_003dCSV-and-TYPE_003dTAB.md","filePath":"manual-en/SAVE-TRANSLATE-_002fTYPE_003dCSV-and-TYPE_003dTAB.md","lastUpdated":1785684581000}'),n={name:"manual-en/SAVE-TRANSLATE-_002fTYPE_003dCSV-and-TYPE_003dTAB.md"};function s(E,e,o,T,l,d){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h4 id="_9-8-1-writing-comma-and-tab-separated-data-files" tabindex="-1">9.8.1 Writing Comma- and Tab-Separated Data Files <a class="header-anchor" href="#_9-8-1-writing-comma-and-tab-separated-data-files" aria-label="Permalink to &quot;9.8.1 Writing Comma- and Tab-Separated Data Files&quot;">​</a></h4><pre><code>SAVE TRANSLATE
        /OUTFILE={’file_name’,file_handle}
        /TYPE=CSV
        [/REPLACE]
        [/MISSING={IGNORE,RECODE}]

        [/DROP=var_list]
        [/KEEP=var_list]
        [/RENAME=(src_names=target_names)…]
        [/UNSELECTED={RETAIN,DELETE}]

        [/FIELDNAMES]
        [/CELLS={VALUES,LABELS}]
        [/TEXTOPTIONS DELIMITER=’delimiter’]
        [/TEXTOPTIONS QUALIFIER=’qualifier’]
        [/TEXTOPTIONS DECIMAL={DOT,COMMA}]
        [/TEXTOPTIONS FORMAT={PLAIN,VARIABLE}]
</code></pre><p>The SAVE TRANSLATE command with TYPE=CSV or TYPE=TAB writes data in a comma- or tab-separated value format similar to that described by RFC 4180. Each variable becomes one output column, and each case becomes one line of output. If FIELDNAMES is specified, an additional line at the top of the output file lists variable names.</p><p>The CELLS and TEXTOPTIONS FORMAT settings determine how values are written to the output file:</p><p>CELLS=VALUES FORMAT=PLAIN (the default settings)</p><p>Writes variables to the output in “plain” formats that ignore the details of variable formats. Numeric values are written as plain decimal numbers with enough digits to indicate their exact values in machine representation. Numeric values include ‘e’ followed by an exponent if the exponent value would be less than -4 or greater than 16. Dates are written in MM/DD/YYYY format and times in HH:MM:SS format. WKDAY and MONTH values are written as decimal numbers.</p><p>Numeric values use, by default, the decimal point character set with SET DECIMAL (see <a href="./SET#SET-DECIMAL">SET DECIMAL</a>). Use DECIMAL=DOT or DECIMAL=COMMA to force a particular decimal point character.</p><p>CELLS=VALUES FORMAT=VARIABLE</p><p>Writes variables using their print formats. Leading and trailing spaces are removed from numeric values, and trailing spaces are removed from string values.</p><p>CELLS=LABEL FORMAT=PLAIN CELLS=LABEL FORMAT=VARIABLE</p><p>Writes value labels where they exist, and otherwise writes the values themselves as described above.</p><p>Regardless of CELLS and TEXTOPTIONS FORMAT, numeric system-missing values are output as a single space.</p><p>For TYPE=TAB, tab characters delimit values. For TYPE=CSV, the TEXTOPTIONS DELIMITER and DECIMAL settings determine the character that separate values within a line. If DELIMITER is specified, then the specified string separate values. If DELIMITER is not specified, then the default is a comma with DECIMAL=DOT or a semicolon with DECIMAL=COMMA. If DECIMAL is not given either, it is implied by the decimal point character set with SET DECIMAL (see <a href="./SET#SET-DECIMAL">SET DECIMAL</a>).</p><p>The TEXTOPTIONS QUALIFIER setting specifies a character that is output before and after a value that contains the delimiter character or the qualifier character. The default is a double quote (‘&quot;’). A qualifier character that appears within a value is doubled.</p>`,14)])])}const p=a(n,[["render",s]]);export{A as __pageData,p as default};
